-- RBAC 8/8 (epic #183, issue #191): contract phase.
--
-- DO NOT DEPLOY until the earlier RBAC phases (0038-0040) have been live for at
-- least one release (see docs/DATABASE-MIGRATION.md, "RBAC 8/8 rollout"). This
-- migration removes what the previous app version still relied on:
--   * team_members.event_id becomes NOT NULL,
--   * api_keys.key (the legacy plaintext column) is dropped,
--   * the unused user_role enum is dropped,
--   * clan_invites.created_by and discord_webhooks.created_by become nullable.
--
-- Generated by drizzle-kit, then written defensively by hand. Every step is
-- idempotent (a second run is a no-op) and re-checks its precondition: a step
-- whose data is not ready is skipped with a NOTICE instead of failing the
-- deploy, and the verification queries (npm run db:verify-rbac) report it.

-- ---------------------------------------------------------------------------
-- 1. Creators: every Event whose creator has no participant row gets an admin
--    row, and a creator with a lower explicit role is promoted to admin. The
--    app no longer treats the creator as admin by itself (the "creator
--    shortcut" of the old role lookup is gone), so this must hold for every
--    Event before the new app starts. Rows are logged in the ledger as
--    'backfill' / 'change' (source 'migration'); app.audit_source keeps the
--    safety-net trigger from logging them a second time.
-- ---------------------------------------------------------------------------
SELECT set_config('app.audit_source', 'migration', true);--> statement-breakpoint
WITH inserted AS (
  INSERT INTO "bingoscape-next_event_participants" ("event_id", "user_id", "role")
  SELECT e."id", e."creator_id", 'admin'
  FROM "bingoscape-next_events" e
  WHERE e."creator_id" IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM "bingoscape-next_event_participants" ep
      WHERE ep."event_id" = e."id" AND ep."user_id" = e."creator_id"
    )
  ON CONFLICT ("event_id", "user_id") DO NOTHING
  RETURNING "event_id", "user_id"
)
INSERT INTO "bingoscape-next_role_change_log"
  ("scope_type", "scope_id", "subject_user_id", "action", "old_role", "new_role", "source", "reason")
SELECT 'event', i."event_id", i."user_id", 'backfill', NULL, 'admin', 'migration', 'creator admin row added by migration 0045'
FROM inserted i;--> statement-breakpoint
WITH targets AS (
  SELECT ep."id", ep."event_id", ep."user_id", ep."role"::text AS "old_role"
  FROM "bingoscape-next_event_participants" ep
  INNER JOIN "bingoscape-next_events" e ON e."id" = ep."event_id" AND e."creator_id" = ep."user_id"
  WHERE ep."role" <> 'admin'
), promoted AS (
  UPDATE "bingoscape-next_event_participants" ep
  SET "role" = 'admin', "updated_at" = now()
  FROM targets t
  WHERE ep."id" = t."id"
  RETURNING ep."id"
)
INSERT INTO "bingoscape-next_role_change_log"
  ("scope_type", "scope_id", "subject_user_id", "action", "old_role", "new_role", "source", "reason")
SELECT 'event', t."event_id", t."user_id", 'change', t."old_role", 'admin', 'migration', 'creator promoted to admin by migration 0045'
FROM targets t
INNER JOIN promoted p ON p."id" = t."id";--> statement-breakpoint
SELECT set_config('app.audit_source', '', true);--> statement-breakpoint

-- ---------------------------------------------------------------------------
-- 2. team_members.event_id NOT NULL. The previous app version may still have
--    inserted rows without event_id after migration 0038, so the backfill runs
--    again first. Rows that would now collide on (event_id, user_id) (a Player
--    put on two Teams of one Event by that version) are moved to the
--    quarantine table first: keep the leader row, then the oldest, as in 0038.
--    If a NULL remains after that (it cannot, every row has a Team), the
--    constraint is skipped with a NOTICE.
-- ---------------------------------------------------------------------------
INSERT INTO "bingoscape-next_team_members_quarantine"
  ("reason", "original_id", "team_id", "event_id", "user_id", "is_leader", "original_created_at", "original_updated_at", "kept_team_member_id", "kept_team_id")
SELECT 'multiple_teams_in_event', r."id", r."team_id", r."team_event_id", r."user_id", r."is_leader", r."created_at", r."updated_at", r."keeper_id", r."keeper_team_id"
FROM (
  SELECT tm.*, t."event_id" AS "team_event_id",
         first_value(tm."id") OVER w AS "keeper_id",
         first_value(tm."team_id") OVER w AS "keeper_team_id",
         row_number() OVER w AS "rn"
  FROM "bingoscape-next_team_members" tm
  INNER JOIN "bingoscape-next_teams" t ON t."id" = tm."team_id"
  WINDOW w AS (
    PARTITION BY t."event_id", tm."user_id"
    ORDER BY tm."is_leader" DESC, tm."created_at" ASC, tm."id" ASC
  )
) r
WHERE r."rn" > 1
ON CONFLICT ("original_id") DO NOTHING;--> statement-breakpoint
DELETE FROM "bingoscape-next_team_members" tm
USING (
  SELECT tm2."id",
         row_number() OVER (
           PARTITION BY t2."event_id", tm2."user_id"
           ORDER BY tm2."is_leader" DESC, tm2."created_at" ASC, tm2."id" ASC
         ) AS "rn"
  FROM "bingoscape-next_team_members" tm2
  INNER JOIN "bingoscape-next_teams" t2 ON t2."id" = tm2."team_id"
) r
WHERE tm."id" = r."id" AND r."rn" > 1;--> statement-breakpoint
UPDATE "bingoscape-next_team_members" tm
SET "event_id" = t."event_id"
FROM "bingoscape-next_teams" t
WHERE tm."team_id" = t."id" AND tm."event_id" IS NULL;--> statement-breakpoint
DO $$
DECLARE
  remaining bigint;
BEGIN
  SELECT count(*) INTO remaining FROM "bingoscape-next_team_members" WHERE "event_id" IS NULL;
  IF remaining > 0 THEN
    RAISE NOTICE 'RBAC 8/8: % team_members row(s) still have no event_id; NOT NULL skipped (see the team_members_missing_event_id check of npm run db:verify-rbac)', remaining;
  ELSE
    ALTER TABLE "bingoscape-next_team_members" ALTER COLUMN "event_id" SET NOT NULL;
  END IF;
END $$;--> statement-breakpoint

-- ---------------------------------------------------------------------------
-- 3. api_keys.key (legacy plaintext) is dropped, but only when no row still
--    depends on it. First every key without a hash gets its hash and prefix
--    (exactly as 0040 did: PostgreSQL 11+ sha256(bytea), no pgcrypto). If a
--    key still has no hash afterwards (cannot happen), the column is kept and a
--    NOTICE is raised. Dropping the column drops its unique constraint.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  remaining bigint;
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = current_schema()
      AND table_name = 'bingoscape-next_api_keys'
      AND column_name = 'key'
  ) THEN
    EXECUTE $q$
      UPDATE "bingoscape-next_api_keys"
      SET "key_hash" = encode(sha256(convert_to("key", 'UTF8')), 'hex'),
          "key_prefix" = left("key", 8)
      WHERE "key" IS NOT NULL AND "key_hash" IS NULL
    $q$;
    EXECUTE $q$
      SELECT count(*) FROM "bingoscape-next_api_keys"
      WHERE "key" IS NOT NULL AND "key_hash" IS NULL
    $q$ INTO remaining;
    IF remaining > 0 THEN
      RAISE NOTICE 'RBAC 8/8: % api_keys row(s) still have no key_hash; the legacy "key" column is kept', remaining;
    ELSE
      ALTER TABLE "bingoscape-next_api_keys" DROP COLUMN "key";
    END IF;
  END IF;
END $$;--> statement-breakpoint

-- ---------------------------------------------------------------------------
-- 4. clan_invites.created_by: the column was NOT NULL with ON DELETE SET NULL,
--    so deleting the user who made an invite failed. The invite belongs to the
--    Clan and outlives its creator: the column becomes nullable and the
--    foreign key keeps setting it to NULL. Idempotent by nature.
-- ---------------------------------------------------------------------------
ALTER TABLE "bingoscape-next_clan_invites" ALTER COLUMN "created_by" DROP NOT NULL;--> statement-breakpoint

-- ---------------------------------------------------------------------------
-- 4b. discord_webhooks.created_by: the foreign key was ON DELETE CASCADE, so
--     deleting the user who created a webhook silently removed the Event's
--     webhook. The webhook belongs to the Event and outlives its creator: the
--     column becomes nullable and the foreign key sets it to NULL. Idempotent.
-- ---------------------------------------------------------------------------
ALTER TABLE "bingoscape-next_discord_webhooks" DROP CONSTRAINT IF EXISTS "bingoscape-next_discord_webhooks_created_by_bingoscape-next_user_id_fk";--> statement-breakpoint
ALTER TABLE "bingoscape-next_discord_webhooks" ALTER COLUMN "created_by" DROP NOT NULL;--> statement-breakpoint
DO $$ BEGIN
  ALTER TABLE "bingoscape-next_discord_webhooks" ADD CONSTRAINT "bingoscape-next_discord_webhooks_created_by_bingoscape-next_user_id_fk" FOREIGN KEY ("created_by") REFERENCES "public"."bingoscape-next_user"("id") ON DELETE set null ON UPDATE no action;
EXCEPTION
  WHEN duplicate_object THEN null;
END $$;--> statement-breakpoint

-- ---------------------------------------------------------------------------
-- 5. The user_role enum has no column using it (roles live in the
--    event_participants / clan_members enums). Dropped unless something still
--    depends on it.
-- ---------------------------------------------------------------------------
DO $$ BEGIN
  DROP TYPE IF EXISTS "public"."user_role";
EXCEPTION
  WHEN dependent_objects_still_exist THEN
    RAISE NOTICE 'RBAC 8/8: type user_role is still in use; kept';
END $$;
